-- Hibernate PanacheEntity default id generation (no @GeneratedValue strategy)
-- uses SEQUENCE {table}_SEQ with allocationSize = 50.
-- Schema validation therefore requires every entity table sequence to exist
-- with INCREMENT BY 50. Some were created by migrations with INCREMENT 1
-- (e.g. roles_seq), so ALTER them; create the missing ones.
ALTER SEQUENCE IF EXISTS billing_statements_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS billing_statements_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS card_auth_transactions_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS card_auth_transactions_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS card_event_logs_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS card_event_logs_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS card_payments_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS card_payments_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS card_rewards_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS card_rewards_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS cards_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS cards_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS merchant_documents_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS merchant_documents_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS merchants_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS merchants_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS refresh_tokens_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS refresh_tokens_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS reset_tokens_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS reset_tokens_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS roles_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS roles_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS saldo_mutation_operations_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS saldo_mutation_operations_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS saldos_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS saldos_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS topups_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS topups_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS transactions_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS transactions_seq INCREMENT BY 50 START WITH 1;

ALTER SEQUENCE IF EXISTS transfers_seq INCREMENT BY 50;
CREATE SEQUENCE IF NOT EXISTS transfers_seq INCREMENT BY 50 START WITH 1;

